package com.blighteddreams.helper.client;

import com.blighteddreams.helper.BlightedHelper;
import com.blighteddreams.helper.HelperEntity;
import com.blighteddreams.helper.HelperVariant;
import net.minecraft.resources.ResourceLocation;
import software.bernie.geckolib.model.GeoModel;

/**
 * One GeckoLib model per variant: geo/&lt;id&gt;.geo.json, textures/entity/&lt;id&gt;.png (+ &lt;id&gt;_glowmask.png), animations/&lt;id&gt;.animation.json.
 * All of them are generated by design/entitykit (node build.js --install); the animation clips are the same set for every variant.
 */
public class HelperGeoModel extends GeoModel<HelperEntity> {
    private static String idOf(HelperVariant v) {
        return switch (v) {
            case DEMON -> "demon";
            case ANGEL -> "angel";
            case ASTRAL -> "astral";
            case JESTER -> "jester";
            default -> "emily";
        };
    }

    private static ResourceLocation res(String path) {
        return ResourceLocation.fromNamespaceAndPath(BlightedHelper.MOD_ID, path);
    }

    @Override
    public ResourceLocation getModelResource(HelperEntity animatable) {
        return res("geo/" + idOf(animatable.getVariant()) + ".geo.json");
    }

    @Override
    public ResourceLocation getTextureResource(HelperEntity animatable) {
        return res("textures/entity/" + idOf(animatable.getVariant()) + ".png");
    }

    @Override
    public ResourceLocation getAnimationResource(HelperEntity animatable) {
        return res("animations/" + idOf(animatable.getVariant()) + ".animation.json");
    }
}
